function validate([s, target]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100) return 's needs 1 to 100 letters.';
  if (typeof target !== 'string' || target.length < 1 || target.length > 10) return 'target needs 1 to 10 letters.';
  if (!/^[a-z]+$/.test(s) || !/^[a-z]+$/.test(target)) return 'Use lowercase English letters only.';
  return null;
}

