function rearrangeCharacters(s, target) {
  const pool = s.split('');
  let built = 0;
  for (;;) {
    for (const ch of target) {
      const at = pool.indexOf(ch);
      if (at === -1) return built;
      pool.splice(at, 1);
    }
    built++;
  }
}

