function generate(rand, size) {
  const small = size === 'small';
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const k = small ? 1 + Math.floor(rand() * 4) : 1 + Math.floor(rand() * 8);
  const start = Math.floor(rand() * (26 - k + 1));
  const alphabet = letters.slice(start, start + k);
  const pick = () => alphabet[Math.floor(rand() * alphabet.length)];
  const n = small ? 1 + Math.floor(rand() * 15) : 100;
  const m = small ? 1 + Math.floor(rand() * 4) : 1 + Math.floor(rand() * 10);
  let s = '';
  for (let i = 0; i < n; i++) s += pick();
  let target = '';
  for (let i = 0; i < m; i++) target += rand() < 0.1 ? letters[Math.floor(rand() * 26)] : pick();
  return [s, target];
}
